const $=id=>document.getElementById(id);
let stream=null,current=null,db=null,historyStack=[],historyIndex=-1,currentProjectId=null;
const VERSION='32', BACKEND_KEY='carmen_phone_backend_v24',URL_KEY='carmen_last_url_v24',DB_NAME='carmen-phone-v24';
window.addEventListener('error',e=>{try{console.error(e.error||e.message)}catch(_){}});window.addEventListener('unhandledrejection',e=>{try{console.error(e.reason)}catch(_){}});
$('backend').value=localStorage.getItem(BACKEND_KEY)||location.origin;
function toast(s){$('toast').textContent=s;$('toast').classList.remove('hidden');clearTimeout(window.__toast);window.__toast=setTimeout(()=>$('toast').classList.add('hidden'),3000)}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function normalizeUrl(s){s=s.trim();if(!s)return '';if(!/^https?:\/\//i.test(s))return 'https://'+s;return s}
function openDB(){return new Promise((res,rej)=>{const r=indexedDB.open(DB_NAME,2);r.onupgradeneeded=()=>{const d=r.result;if(!d.objectStoreNames.contains('projects'))d.createObjectStore('projects',{keyPath:'id'});if(!d.objectStoreNames.contains('refs'))d.createObjectStore('refs',{keyPath:'id'});if(!d.objectStoreNames.contains('events'))d.createObjectStore('events',{keyPath:'id'});if(!d.objectStoreNames.contains('leads'))d.createObjectStore('leads',{keyPath:'id'});if(!d.objectStoreNames.contains('queue'))d.createObjectStore('queue',{keyPath:'id'});if(!d.objectStoreNames.contains('sessions'))d.createObjectStore('sessions',{keyPath:'id'});if(!d.objectStoreNames.contains('deepdives'))d.createObjectStore('deepdives',{keyPath:'id'});};r.onsuccess=()=>{db=r.result;res(db)};r.onerror=()=>rej(r.error)})}
function put(store,v){return new Promise((res,rej)=>{const t=db.transaction(store,'readwrite');t.objectStore(store).put(v);t.oncomplete=()=>res(v);t.onerror=()=>rej(t.error)})}
function all(store){return new Promise((res,rej)=>{const t=db.transaction(store);const r=t.objectStore(store).getAll();r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}
function delAll(store){return new Promise((res,rej)=>{const t=db.transaction(store,'readwrite');t.objectStore(store).clear();t.oncomplete=()=>res();t.onerror=()=>rej(t.error)})}
function openLegacy(name){return new Promise((res,rej)=>{const r=indexedDB.open(name);r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error);r.onupgradeneeded=()=>{r.transaction.abort();rej(new Error('legacy database does not exist'))}})}
function readFrom(d,store){return new Promise((res,rej)=>{if(!d.objectStoreNames.contains(store))return res([]);const t=d.transaction(store);const q=t.objectStore(store).getAll();q.onsuccess=()=>res(q.result);q.onerror=()=>rej(q.error)})}
async function migrateLegacy(){const marker='carmen_migrated_v18_to_v23';if(localStorage.getItem(marker))return;let old;try{old=await openLegacy('carmen-phone-v18')}catch{localStorage.setItem(marker,'1');return}try{const [projects,refs,events]=await Promise.all([readFrom(old,'projects'),readFrom(old,'refs'),readFrom(old,'events')]);const current=await all('projects');for(const x of projects)if(!current.some(p=>p.id===x.id))await put('projects',x);for(const x of refs)if(!(await all('refs')).some(r=>r.id===x.id))await put('refs',{...x,projectId:x.projectId||projects[0]?.id});for(const x of events)if(!(await all('events')).some(e=>e.id===x.id))await put('events',{...x,projectId:x.projectId||projects[0]?.id});localStorage.setItem(marker,'1');toast('Older Carmen evidence migrated.')}catch(e){console.warn('V18 migration failed',e)}finally{old.close()}}
async function migrateV19(){const marker='carmen_migrated_v19_to_v23';if(localStorage.getItem(marker))return;let old;try{old=await openLegacy('carmen-phone-v19')}catch{localStorage.setItem(marker,'1');return}try{const [projects,refs,events,leads]=await Promise.all([readFrom(old,'projects'),readFrom(old,'refs'),readFrom(old,'events'),readFrom(old,'leads')]);const stores=[['projects',projects],['refs',refs],['events',events],['leads',leads]];for(const [store,items] of stores){const existing=await all(store);for(const x of items)if(!existing.some(y=>y.id===x.id))await put(store,x)}localStorage.setItem(marker,'1');toast('V19 data migrated into V20.')}catch(e){console.warn('V19 migration failed',e)}finally{old.close()}}
async function migrateV20(){const marker='carmen_migrated_v20_to_v23';if(localStorage.getItem(marker))return;let old;try{old=await openLegacy('carmen-phone-v20')}catch{localStorage.setItem(marker,'1');return}try{const [projects,refs,events,leads]=await Promise.all([readFrom(old,'projects'),readFrom(old,'refs'),readFrom(old,'events'),readFrom(old,'leads')]);for(const x of projects)await put('projects',x);for(const x of refs)await put('refs',x);for(const x of events)await put('events',x);for(const x of leads)await put('leads',x);localStorage.setItem(marker,'1');toast('V20 data migrated into V23.')}catch(e){console.warn('V20 migration failed',e)}finally{old.close()}}
async function migrateV23(){const marker='carmen_migrated_v23_to_v24';if(localStorage.getItem(marker))return;let old;try{old=await openLegacy('carmen-phone-v23')}catch{localStorage.setItem(marker,'1');return}try{const [projects,refs,events,leads,queue]=await Promise.all([readFrom(old,'projects'),readFrom(old,'refs'),readFrom(old,'events'),readFrom(old,'leads'),readFrom(old,'queue')]);for(const x of projects)await put('projects',x);for(const x of refs)await put('refs',x);for(const x of events)await put('events',x);for(const x of leads)await put('leads',x);for(const x of queue)await put('queue',x);localStorage.setItem(marker,'1');toast('V23 data migrated into V24.')}catch(e){console.warn('V23 migration failed',e)}finally{old.close()}}
async function migrateV22(){const marker='carmen_migrated_v22_to_v23';if(localStorage.getItem(marker))return;let old;try{old=await openLegacy('carmen-phone-v22')}catch{localStorage.setItem(marker,'1');return}try{const [projects,refs,events,leads,queue]=await Promise.all([readFrom(old,'projects'),readFrom(old,'refs'),readFrom(old,'events'),readFrom(old,'leads'),readFrom(old,'queue')]);for(const x of projects)await put('projects',x);for(const x of refs)await put('refs',x);for(const x of events)await put('events',x);for(const x of leads)await put('leads',x);for(const x of queue)await put('queue',x);localStorage.setItem(marker,'1');toast('V22 data migrated into V23.')}catch(e){console.warn('V22 migration failed',e)}finally{old.close()}}
async function migrateV21(){const marker='carmen_migrated_v21_to_v23';if(localStorage.getItem(marker))return;let old;try{old=await openLegacy('carmen-phone-v21')}catch{localStorage.setItem(marker,'1');return}try{const [projects,refs,events,leads]=await Promise.all([readFrom(old,'projects'),readFrom(old,'refs'),readFrom(old,'events'),readFrom(old,'leads')]);for(const x of projects)await put('projects',x);for(const x of refs)await put('refs',x);for(const x of events)await put('events',x);for(const x of leads)await put('leads',x);localStorage.setItem(marker,'1');toast('V21 data migrated into V23.')}catch(e){console.warn('V21 migration failed',e)}finally{old.close()}}
async function ensureProject(){let ps=await all('projects');if(!ps.length){const p={id:'project_'+crypto.randomUUID(),name:'My first investigation',question:'',createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()};await put('projects',p);ps=[p]}currentProjectId=currentProjectId&&ps.some(p=>p.id===currentProjectId)?currentProjectId:ps[0].id;renderProjects(ps);$('projectQuestion').value=ps.find(p=>p.id===currentProjectId)?.question||'';await refresh()}
function renderProjects(ps){$('projectSelect').innerHTML=ps.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('');$('projectSelect').value=currentProjectId}
function sourceTypeLabel(v){return ({adult_video:'Adult video',reddit:'Reddit',web:'Web',other:'Other'}[v]||'Web')}
function currentSourceType(){return $('sourceType')?.value||'web'}
async function refresh(){const refs=await all('refs'),events=await all('events'),allLeads=await all('leads');const projectRefs=refs.filter(r=>r.projectId===currentProjectId),projectLeads=allLeads.filter(x=>x.projectId===currentProjectId);$('refs').textContent=projectRefs.length;$('events').textContent=events.filter(e=>e.projectId===currentProjectId).length;const p=buildPatterns(projectRefs);$('patterns').textContent=p.length;renderPatternBoard(projectRefs);renderArchive(projectRefs);renderSourceStats(projectRefs);renderDashboard(projectRefs);const queue=(await all('queue')).filter(q=>q.projectId===currentProjectId);$('queueCount').textContent=queue.filter(q=>q.status==='queued').length;renderQueue(queue);$('projectCount').textContent=`${projectRefs.length} evidence item${projectRefs.length===1?'':'s'}`;renderLeads(projectLeads);renderDeepDive(projectRefs);renderEvidenceGraph();renderIntelligence();
  renderWorkspace();const next=projectLeads.find(l=>l.status==='new');$('nextMove').textContent=next?`Review this lead: ${next.text}`:queue.some(q=>q.status==='queued')?`Open the next queued source: ${queue.find(q=>q.status==='queued')?.label||'research item'}.`:projectRefs.length<2?'Capture another piece of evidence so Carmen can compare them.':p.length?'Compare evidence around one of the recurring patterns.':'Analyze more evidence to build recurring patterns.'}
function patternKey(s){return String(s||'').toLowerCase().replace(/[^a-z0-9\s-]/g,' ').replace(/\s+/g,' ').trim()}
function patternTokens(s){return new Set(patternKey(s).split(' ').filter(w=>w.length>2&&!['the','and','with','that','this','from','visible','appears','likely','possibly'].includes(w)))}
function similarity(a,b){const A=patternTokens(a),B=patternTokens(b);if(!A.size||!B.size)return 0;let hit=0;for(const x of A)if(B.has(x))hit++;return hit/(A.size+B.size-hit)}
function buildPatterns(refs){const groups=[];for(const r of refs){for(const raw of (r.candidatePatterns||[])){const label=String(raw.text||raw).trim();if(!label)continue;let g=groups.find(x=>similarity(x.label,label)>=.62);if(!g){g={label,support:0,evidenceIds:new Set(),firstSeen:r.createdAt,lastSeen:r.createdAt};groups.push(g)}g.support++;g.evidenceIds.add(r.id);if(r.createdAt<g.firstSeen)g.firstSeen=r.createdAt;if(r.createdAt>g.lastSeen)g.lastSeen=r.createdAt}}return groups.map(g=>({...g,evidenceIds:[...g.evidenceIds],evidenceCount:g.evidenceIds.size,confidence:g.evidenceIds.size>=3?'strong recurring':g.evidenceIds.size>=2?'recurring':'emerging'})).sort((a,b)=>b.evidenceCount-a.evidenceCount||b.support-a.support)}
function renderPatternBoard(refs){const ps=buildPatterns(refs);$('patternBoard').innerHTML=ps.map(p=>`<div class="pattern"><b>${esc(p.label)}</b> <span class="badge">${esc(p.confidence)}</span><div class="patternbar"><span style="width:${Math.min(100,p.evidenceCount/Math.max(1,refs.length)*100)}%"></span></div><small>${p.evidenceCount} of ${refs.length} evidence items support this hypothesis · ${p.support} mentions</small></div>`).join('')||'<span class="muted">No recurring pattern hypotheses yet. Analyze more evidence to build the board.</span>';return ps}
function renderArchive(refs){const q=String($('archiveSearch')?.value||'').trim().toLowerCase();const filtered=!q?refs:refs.filter(r=>[r.title,r.url,r.context,r.signature,...(r.observations||[]).map(x=>x.text||x),...(r.candidatePatterns||[]).map(x=>x.text||x)].join(' ').toLowerCase().includes(q));$('archive').innerHTML=filtered.slice().reverse().map(r=>`<label class="refitem"><input type="checkbox" class="refcheck" value="${esc(r.id)}"><span><b>${esc(r.title||r.url||r.id)}</b> <span class="badge">${esc(r.source||'capture')}</span><br><small>${new Date(r.createdAt).toLocaleString()}${r.url?' · '+esc(r.url):''}</small><br>${(r.observations||[]).slice(0,2).map(x=>esc(x.text||x)).join(' · ')||esc(r.context||'')}</span></label>`).join('')||'<span class="muted">No matching evidence in this investigation.</span>'}
async function sha(s){const b=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(s));return [...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,'0')).join('')}
async function backfillFingerprints(){const refs=await all('refs');for(const r of refs){if(!r.fingerprint&&r.imageDataUrl){r.fingerprint=await sha(r.imageDataUrl);await put('refs',r)}}}
function evidenceHealth(refs){const n=refs.length;if(!n)return {score:0,label:'No evidence yet',tips:['Capture your first reference.']};let score=0;const typed=refs.filter(r=>r.sourceType).length;const contextual=refs.filter(r=>String(r.context||'').trim()).length;const analyzed=refs.filter(r=>Array.isArray(r.observations)&&r.observations.length).length;score=Math.round((typed/n*.25+contextual/n*.2+analyzed/n*.35+Math.min(1,n/5)*.2)*100);let tips=[];if(typed<n)tips.push(`${n-typed} reference${n-typed===1?'':'s'} missing a source type.`);if(contextual<n)tips.push('Add context or a research question to more captures.');if(analyzed<n)tips.push('Analyze more saved captures.');if(n<5)tips.push(`Add ${5-n} more reference${5-n===1?'':'s'} for a stronger comparison set.`);return {score,label:score>=80?'Strongly documented':score>=55?'Developing':'Needs more documentation',tips}}
function renderDashboard(refs){const h=evidenceHealth(refs);const box=$('evidenceHealth');if(box)box.innerHTML=`<div class=\"stat\"><div><div class=\"num\">${h.score}%</div><small>Documentation</small></div><div><div class=\"num\">${refs.filter(r=>r.sourceType).length}</div><small>Typed sources</small></div><div><div class=\"num\">${refs.filter(r=>Array.isArray(r.observations)&&r.observations.length).length}</div><small>Analyzed</small></div></div><p><b>${esc(h.label)}</b></p><small>${h.tips.map(esc).join(' · ')}</small>`;const timeline=$('timeline');if(timeline)timeline.innerHTML=refs.slice().sort((a,b)=>String(b.createdAt).localeCompare(String(a.createdAt))).slice(0,8).map(r=>`<div class=\"pattern\"><b>${esc(r.title||r.url||'Evidence')}</b> <span class=\"badge\">${esc(sourceTypeLabel(r.sourceType||'web'))}</span><br><small>${new Date(r.createdAt).toLocaleString()} · ${esc(r.sourceName||queueDomain(r.url)||'source')}</small></div>`).join('')||'<span class=\"muted\">Your recent evidence timeline will appear here.</span>'}
function sourceStats(refs){const m={};for(const r of refs){const type=sourceTypeLabel(r.sourceType||'web'),name=r.sourceName||queueDomain(r.url)||'Unknown source';const k=type+'|'+name;if(!m[k])m[k]={type,name,count:0,last:r.createdAt};m[k].count++;if(r.createdAt>m[k].last)m[k].last=r.createdAt}return Object.values(m).sort((a,b)=>b.count-a.count)}
function renderSourceStats(refs){const box=$('sourceStats');if(!box)return;const rows=sourceStats(refs);box.innerHTML=rows.map(x=>`<div class=\"pattern\"><b>${esc(x.name)}</b> <span class=\"badge\">${esc(x.type)}</span><br><small>${x.count} evidence item${x.count===1?'':'s'} · last captured ${new Date(x.last).toLocaleString()}</small></div>`).join('')||'<span class=\"muted\">No source statistics yet.</span>'}
function queueDomain(u){try{return new URL(normalizeUrl(u)).hostname.replace(/^www\./,'')}catch{return ''}}
function renderQueue(items){const box=$('queueList');if(!box)return;const f=$('queueFilter')?.value||'all';const arr=items.filter(x=>f==='all'||x.status===f).sort((a,b)=>String(b.createdAt).localeCompare(String(a.createdAt)));box.innerHTML=arr.map(x=>`<div class=\"lead\"><div><b>${esc(x.label||x.url)}</b> <span class=\"badge\">${esc(x.status)}</span> <span class=\"badge\">${esc(sourceTypeLabel(x.sourceType))}</span></div><small>${esc(queueDomain(x.url))}${x.note?' · '+esc(x.note):''}</small><div class=\"row\" style=\"margin-top:8px\"><button data-queue=\"open\" data-id=\"${esc(x.id)}\">Open</button><button data-queue=\"done\" data-id=\"${esc(x.id)}\">${x.status==='completed'?'Re-queue':'Mark done'}</button><button data-queue=\"delete\" data-id=\"${esc(x.id)}\">Remove</button></div></div>`).join('')||'<span class=\"muted\">No research items in this queue.</span>'}
async function addQueue(){const url=normalizeUrl($('queueUrl').value);if(!url)return toast('Enter a URL first.');const q={id:'queue_'+crypto.randomUUID(),projectId:currentProjectId,createdAt:new Date().toISOString(),updatedAt:new Date().toISOString(),url,label:$('queueLabel').value.trim()||queueDomain(url),sourceType:$('queueSourceType').value,note:$('queueNote').value.trim(),status:'queued'};await put('queue',q);$('queueUrl').value='';$('queueLabel').value='';$('queueNote').value='';await (async()=>{try{await openDB();await refresh()}catch(e){console.error(e);toast('Carmen storage could not be opened. Try reloading the app.')}})();toast('Added to research queue.')}
$('queueAdd').onclick=addQueue;$('queueFilter').onchange=async()=>renderQueue((await all('queue')).filter(q=>q.projectId===currentProjectId));$('queueList').onclick=async e=>{const b=e.target.closest('[data-queue]');if(!b)return;const id=b.dataset.id,act=b.dataset.queue,qs=await all('queue'),q=qs.find(x=>x.id===id);if(!q)return;if(act==='open'){navigate(q.url);setTab('browse');return}if(act==='done'){q.status=q.status==='completed'?'queued':'completed';q.updatedAt=new Date().toISOString();await put('queue',q)}if(act==='delete'){if(!confirm('Remove this research item from the queue?'))return;await new Promise((res,rej)=>{const t=db.transaction('queue','readwrite');t.objectStore('queue').delete(id);t.oncomplete=res;t.onerror=()=>rej(t.error)})}await refresh()};
function setTab(name){for(const [id,view] of [['tabBrowse','browseView'],['tabEvidence','evidenceView'],['tabArchive','archiveView'],['tabWorkspace','workspaceView'],['tabDeepDive','deepDiveView'],['tabGraph','graphView'],['tabIntelligence','intelligenceView'],['tabLeads','leadsView']]){$(id)?.classList.toggle('active',id.toLowerCase().includes(name));$(view)?.classList.toggle('hidden',view!==name+'View')}for(const id of ['navBrowse','navEvidence','navArchive','navWorkspace','navDeepDive','navGraph','navIntelligence','navLeads'])$(id)?.classList.toggle('active',id.toLowerCase().includes(name))}
$('tabBrowse').onclick=()=>setTab('browse');$('tabEvidence').onclick=()=>setTab('evidence');$('tabArchive').onclick=()=>setTab('archive');$('tabLeads').onclick=()=>setTab('leads');$('tabIntelligence').onclick=()=>setTab('intelligence');$('navIntelligence').onclick=()=>setTab('intelligence');
$('navBrowse').onclick=()=>setTab('browse');$('navEvidence').onclick=()=>setTab('evidence');$('navArchive').onclick=()=>setTab('archive');$('navLeads').onclick=()=>setTab('leads');$('quickCapture').onclick=()=>{setTab('browse');$('pick').click()};$('quickArchive').onclick=()=>setTab('archive');$('quickLeads').onclick=()=>setTab('leads');$('quickCompare').onclick=()=>{setTab('archive');$('researchQuestion').focus()};$('quickIntelligence').onclick=()=>setTab('intelligence');$('importBtn').onclick=()=>$('importFile').click();
$('projectSelect').onchange=async()=>{currentProjectId=$('projectSelect').value;const ps=await all('projects');$('projectQuestion').value=ps.find(p=>p.id===currentProjectId)?.question||'';await refresh()};
$('newProject').onclick=async()=>{const name=prompt('Name this investigation:','New investigation');if(!name?.trim())return;const p={id:'project_'+crypto.randomUUID(),name:name.trim(),question:'',createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()};await put('projects',p);currentProjectId=p.id;renderProjects(await all('projects'));$('projectQuestion').value='';await refresh();toast('Investigation created.')};
$('renameProject').onclick=async()=>{const ps=await all('projects'),p=ps.find(x=>x.id===currentProjectId);if(!p)return;const name=prompt('Rename investigation:',p.name);if(!name?.trim())return;p.name=name.trim();p.updatedAt=new Date().toISOString();await put('projects',p);renderProjects(await all('projects'));toast('Investigation renamed.')};
$('saveProjectQuestion').onclick=async()=>{const ps=await all('projects'),p=ps.find(x=>x.id===currentProjectId);if(!p)return;p.question=$('projectQuestion').value.trim();p.updatedAt=new Date().toISOString();await put('projects',p);toast('Investigation question saved.')};
function navigate(u,push=true){u=normalizeUrl(u);if(!u)return;$('url').value=u;$('webview').src=u;localStorage.setItem(URL_KEY,u);if(push){historyStack=historyStack.slice(0,historyIndex+1);historyStack.push(u);historyIndex=historyStack.length-1}updateNav()}
function updateNav(){$('back').disabled=historyIndex<=0;$('forward').disabled=historyIndex<0||historyIndex>=historyStack.length-1}
$('go').onclick=()=>navigate($('url').value);$('url').addEventListener('keydown',e=>{if(e.key==='Enter')$('go').click()});$('back').onclick=()=>{if(historyIndex>0){historyIndex--;navigate(historyStack[historyIndex],false)}};$('forward').onclick=()=>{if(historyIndex<historyStack.length-1){historyIndex++;navigate(historyStack[historyIndex],false)}};$('reload').onclick=()=>{$('webview').src=$('webview').src};$('openExternal').onclick=()=>{const u=normalizeUrl($('url').value);if(u)location.href=u};$('webview').addEventListener('load',()=>toast('Page loaded.'));
$('pick').onclick=()=>$('file').click();$('file').onchange=()=>{const f=$('file').files?.[0];if(!f)return;if(f.size>12*1024*1024)return toast('Screenshot is too large. Choose one under 12 MB.');const rd=new FileReader();rd.onload=()=>{current=rd.result;showCurrent();enableCapture();setTab('evidence');toast('Screenshot loaded.')};rd.readAsDataURL(f)};
$('start').onclick=async()=>{try{if(!navigator.mediaDevices?.getDisplayMedia)throw Error('Screen capture is not available here. Use Choose screenshot.');stream=await navigator.mediaDevices.getDisplayMedia({video:{frameRate:5},audio:false});$('preview').srcObject=stream;$('preview').classList.remove('hidden');$('start').disabled=true;$('snap').disabled=false;$('stop').disabled=false;stream.getVideoTracks()[0].onended=stop}catch(e){toast(e.message)}};
function stop(){if(stream)stream.getTracks().forEach(t=>t.stop());stream=null;$('preview').srcObject=null;$('preview').classList.add('hidden');$('start').disabled=false;$('snap').disabled=true;$('stop').disabled=true}$('stop').onclick=stop;
$('snap').onclick=()=>{const v=$('preview'),c=$('canvas');const w=Math.min(v.videoWidth||1280,1600),h=Math.round(w*(v.videoHeight||720)/(v.videoWidth||1280));c.width=w;c.height=h;c.getContext('2d').drawImage(v,0,0,w,h);current=c.toDataURL('image/jpeg',.82);showCurrent();enableCapture();setTab('evidence');toast('Frame captured.')};
function enableCapture(){$('analyze').disabled=false;$('save').disabled=false}function showCurrent(){let el=$('captured');if(!el){el=document.createElement('img');el.id='captured';el.className='preview-img';$('capturedWrap').appendChild(el)}el.src=current;el.alt='Current Carmen capture'}function currentUrl(){return normalizeUrl($('url').value)}
async function saveReference(source='iphone-screenshot',data={}){if(!current)return null;const fingerprint=await sha(current);const existing=(await all('refs')).find(r=>r.projectId===currentProjectId&&r.fingerprint===fingerprint);if(existing){toast('This capture is already saved in this investigation.');return existing}const id='ref_'+crypto.randomUUID();const ref={id,projectId:currentProjectId,createdAt:new Date().toISOString(),source,url:currentUrl(),title:data.title||currentUrl(),context:$('context').value,...data,imageDataUrl:current,fingerprint};await put('refs',ref);await put('events',{id:'evt_'+crypto.randomUUID(),projectId:currentProjectId,type:'reference_saved',at:new Date().toISOString(),refId:id});await refresh();return ref}
$('save').onclick=async()=>{if(!current)return toast('Choose or capture a screenshot first.');await saveReference();toast('Saved to this investigation.')};
$('analyze').onclick=async()=>{if(!current)return;const url=$('backend').value.trim().replace(/\/$/,'');if(!url)return toast('Enter the Worker URL first.');localStorage.setItem(BACKEND_KEY,url);$('status').textContent='Carmen is analyzing…';$('analyze').disabled=true;try{const r=await fetch(url+'/analyze',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({imageDataUrl:current,pageContext:$('context').value,pageUrl:currentUrl()})});const text=await r.text();let data;try{data=JSON.parse(text)}catch{throw Error(text||`HTTP ${r.status}`)}if(!r.ok||data.error)throw Error(data.error||`HTTP ${r.status}`);renderAnalysis(data);await saveReference('iphone-screenshot+vision',data);toast('Analyzed and archived.')}catch(e){$('status').textContent='Analysis failed';toast(e.message)}finally{$('analyze').disabled=false;$('status').textContent='Local archive works without a connection.'}};
function list(v){return (v||[]).map(x=>`<div>• ${esc(x.text||x)}</div>`).join('')||'None reported.'}function renderAnalysis(d){$('result').innerHTML=`<div class="claim"><b>${esc(d.title||'Carmen analysis')}</b></div><div class="claim"><b>Observations</b><br>${list(d.observations)}</div><div class="claim"><b>Inferences</b><br>${list(d.inferences)}</div><div class="claim unknown"><b>Unknowns</b><br>${list(d.unknowns)}</div><div class="claim"><b>Relationships</b><br>${list(d.relationships)}</div><div class="claim"><b>Candidate patterns</b><br>${list(d.candidatePatterns)}</div><div class="claim"><b>Signature</b><br>${esc(d.signature||'Not supplied.')}</div>`}
function renderLeads(leads){const box=$('leadList');if(!box)return;const order={new:0,reviewed:1,dismissed:2};leads.sort((a,b)=>(order[a.status]??9)-(order[b.status]??9)||String(b.createdAt).localeCompare(String(a.createdAt)));box.innerHTML=leads.map(l=>`<div class="lead"><div><b>${esc(l.text)}</b> <span class="badge">${esc(l.status)}</span></div><small>${new Date(l.createdAt).toLocaleString()} · ${l.refIds?.length||0} source reference${(l.refIds?.length||0)===1?'':'s'}</small><div class="row" style="margin-top:8px"><button data-lead-action="review" data-id="${esc(l.id)}">${l.status==='reviewed'?'Reviewed':'Mark reviewed'}</button><button data-lead-action="question" data-id="${esc(l.id)}">Use as question</button><button data-lead-action="dismiss" data-id="${esc(l.id)}">Dismiss</button></div></div>`).join('')||'<span class="muted">No research leads yet. Compare evidence to generate leads.</span>'}
async function updateLead(id,patch){const leads=await all('leads'),l=leads.find(x=>x.id===id);if(!l)return;Object.assign(l,patch,{updatedAt:new Date().toISOString()});await put('leads',l);await refresh()}
$('leadList').onclick=async e=>{const b=e.target.closest('[data-lead-action]');if(!b)return;const id=b.dataset.id,action=b.dataset.leadAction,leads=await all('leads'),l=leads.find(x=>x.id===id);if(!l)return;if(action==='review')await updateLead(id,{status:l.status==='reviewed'?'new':'reviewed'});if(action==='dismiss')await updateLead(id,{status:'dismissed'});if(action==='question'){$('researchQuestion').value=l.text;setTab('archive');toast('Lead copied into the comparison question.')}};
