$('health').onclick=async()=>{const u=$('backend').value.trim().replace(/\/$/,'');if(!u)return toast('Enter Worker URL.');localStorage.setItem(BACKEND_KEY,u);try{const r=await fetch(u+'/health');const j=await r.json();if(!r.ok||!j.ok)throw Error(j.error||`HTTP ${r.status}`);$('status').textContent=`Connected · ${j.model||'model'} · research projects ready`;toast('Carmen backend is connected.')}catch(e){$('status').textContent='Connection failed';toast('Could not reach Worker: '+e.message)}};
$('compare').onclick=async()=>{const ids=[...document.querySelectorAll('.refcheck:checked')].map(x=>x.value);if(ids.length<2)return toast('Select at least 2 references.');if(ids.length>4)return toast('Select no more than 4 references.');const refs=await all('refs'),selected=refs.filter(r=>ids.includes(r.id));const url=$('backend').value.trim().replace(/\/$/,'');if(!url)return toast('Enter the Worker URL first.');$('compare').disabled=true;$('compareResult').innerHTML='<p class="muted">Carmen is comparing the selected evidence…</p>';try{const r=await fetch(url+'/synthesize',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({question:$('researchQuestion').value||$('projectQuestion').value,references:selected})});const text=await r.text();let data;try{data=JSON.parse(text)}catch{throw Error(text||`HTTP ${r.status}`)}if(!r.ok||data.error)throw Error(data.error||`HTTP ${r.status}`);$('compareResult').innerHTML=`<div class="claim"><b>Summary</b><br>${esc(data.summary||'')}</div><div class="claim"><b>Consistent findings</b><br>${list(data.consistentFindings)}</div><div class="claim"><b>Differences</b><br>${list(data.differences)}</div><div class="claim"><b>Candidate patterns</b><br>${list(data.candidatePatterns)}</div><div class="claim"><b>Leads</b><br>${list(data.leads)}</div><div class="claim unknown"><b>Unknowns</b><br>${list(data.unknowns)}</div>`;for(const raw of (data.leads||[])){const text=String(raw.text||raw).trim();if(text)await put('leads',{id:'lead_'+crypto.randomUUID(),projectId:currentProjectId,createdAt:new Date().toISOString(),updatedAt:new Date().toISOString(),text,status:'new',refIds:ids,question:$('researchQuestion').value||$('projectQuestion').value})}await put('events',{id:'evt_'+crypto.randomUUID(),projectId:currentProjectId,type:'evidence_synthesis',at:new Date().toISOString(),refIds:ids,question:$('researchQuestion').value||$('projectQuestion').value});await refresh();toast('Comparison complete.')}catch(e){$('compareResult').innerHTML='';toast(e.message)}finally{$('compare').disabled=false}};
