$('importFile').onchange=async()=>{const f=$('importFile').files?.[0];if(!f)return;try{const data=JSON.parse(await f.text());if(!data||!Array.isArray(data.references))throw Error('That file is not a Carmen archive.');const ps=await all('projects');let project=ps.find(p=>p.id===currentProjectId);for(const r of data.references){if(!r.id)continue;const exists=(await all('refs')).some(x=>x.id===r.id);if(!exists)await put('refs',{...r,projectId:currentProjectId})}for(const l of (data.leads||[])){if(l.id&&!((await all('leads')).some(x=>x.id===l.id)))await put('leads',{...l,projectId:currentProjectId})}for(const q of (data.queue||[])){if(q.id&&!((await all('queue')).some(x=>x.id===q.id)))await put('queue',{...q,projectId:currentProjectId})}for(const e of (data.events||[])){if(e.id&&!((await all('events')).some(x=>x.id===e.id)))await put('events',{...e,projectId:currentProjectId})}for(const d of (data.deepdives||[])){if(d.id&&!((await all('deepdives')).some(x=>x.id===d.id)))await put('deepdives',{...d,projectId:currentProjectId})}await refresh();toast('Archive imported into this investigation.')}catch(e){toast('Import failed: '+e.message)}finally{$('importFile').value=''}};
$('export').onclick=async()=>{const payload={version:Number(VERSION),schema:'carmen-v32',exportedAt:new Date().toISOString(),project:(await all('projects')).find(p=>p.id===currentProjectId),references:(await all('refs')).filter(r=>r.projectId===currentProjectId),leads:(await all('leads')).filter(l=>l.projectId===currentProjectId),events:(await all('events')).filter(e=>e.projectId===currentProjectId),queue:(await all('queue')).filter(q=>q.projectId===currentProjectId),deepdives:(await all('deepdives')).filter(d=>d.projectId===currentProjectId)};const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(payload)],{type:'application/json'}));a.download=`carmen-${currentProjectId}-archive.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};
$('clear').onclick=async()=>{if(!confirm('Clear this investigation archive?'))return;const refs=(await all('refs')).filter(r=>r.projectId===currentProjectId),events=(await all('events')).filter(e=>e.projectId===currentProjectId),leads=(await all('leads')).filter(l=>l.projectId===currentProjectId),deepdives=(await all('deepdives')).filter(d=>d.projectId===currentProjectId);for(const r of refs)await new Promise((res,rej)=>{const t=db.transaction('refs','readwrite');t.objectStore('refs').delete(r.id);t.oncomplete=res;t.onerror=()=>rej(t.error)});for(const l of leads)await new Promise((res,rej)=>{const t=db.transaction('leads','readwrite');t.objectStore('leads').delete(l.id);t.oncomplete=res;t.onerror=()=>rej(t.error)});for(const e of events)await new Promise((res,rej)=>{const t=db.transaction('events','readwrite');t.objectStore('events').delete(e.id);t.oncomplete=res;t.onerror=()=>rej(t.error)});for(const q of (await all('queue')).filter(q=>q.projectId===currentProjectId))await new Promise((res,rej)=>{const t=db.transaction('queue','readwrite');t.objectStore('queue').delete(q.id);t.oncomplete=res;t.onerror=()=>rej(t.error)});for(const d of deepdives)await new Promise((res,rej)=>{const t=db.transaction('deepdives','readwrite');t.objectStore('deepdives').delete(d.id);t.oncomplete=res;t.onerror=()=>rej(t.error)});await refresh();toast('Investigation archive cleared.')};
let deferred;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferred=e;$('install').classList.remove('hidden')});$('install').onclick=async()=>{if(deferred){deferred.prompt();deferred=null}};

function deepEsc(s){return esc(s)}
function deepText(x){return String(x?.text??x??'').trim()}
function deepList(items,section,kind){
  const arr=Array.isArray(items)?items:[];
  if(!arr.length)return '<span class="muted">None reported.</span>';
  return arr.map((x,i)=>{
    const text=deepText(x);
    const hazard=String(x?.type||'').toLowerCase().includes('hazard')||String(x?.severity||'').trim().length>0||kind==='hazard';
    const meta=x?.severity?` <span class="badge">${deepEsc(String(x.severity))}</span>`:'';
    return `<div class="deep-item ${hazard?'hazard-item':''}"><div>${hazard?'⚠️ ':'• '}${deepEsc(text)}${meta}</div><div class="branch-actions"><button class="smallbtn branchBtn" data-focus="${deepEsc(text)}" data-kind="${deepEsc(kind||section)}">Explore</button><button class="smallbtn saveSectionBtn" data-text="${deepEsc(text)}" data-section="${deepEsc(section||'section')}" data-kind="${deepEsc(kind||section||'section')}">Save this</button></div></div>`
  }).join('');
}
function renderDeepResult(d){
  if(!d){$('deepResult').innerHTML='';return}
  $('deepResult').innerHTML=`<div class="claim"><b>${deepEsc(d.title||'Deep dive')}</b><div class="branch-actions"><button id="saveDeepResult" class="smallbtn">Save this deep dive</button></div></div>
  <div class="claim"><b>1. Complete deconstruction</b>${deepList(d.deconstruction,'Complete deconstruction','deconstruction')}</div>
  <div class="claim hazard-block"><b>2. Hazards & failure modes</b>${deepList(d.hazards,'Hazards & failure modes','hazard')}</div>
  <div class="claim"><b>3. Safety architecture</b>${deepList(d.safetyArchitecture,'Safety architecture','safety')}</div>
  <div class="claim"><b>4. Physical plausibility</b>${deepList(d.physicalPlausibility,'Physical plausibility','physical')}</div>
  <div class="claim"><b>5. Safer alternatives</b>${deepList(d.alternatives,'Safer alternatives','alternative')}</div>
  <div class="claim"><b>6. Next questions</b>${deepList(d.nextQuestions,'Next questions','question')}</div>
  <div class="claim unknown"><b>Boundary / uncertainty</b>${deepList(d.boundary,'Boundary / uncertainty','boundary')}</div>`;
  bindDeepButtons();
}
function bindDeepButtons(){
  document.querySelectorAll('.branchBtn').forEach(b=>b.onclick=()=>{
    const f=b.dataset.focus||''; const k=b.dataset.kind||'branch';
    $('deepQuestion').value=`Deep dive specifically into this ${k}: ${f}`;
    window.__deepParentId=window.__deepCurrentNodeId||window.__deepParentId||null;
    window.__deepFocus={focus:f,kind:k};
    runDeepDive(f,k);
  });
  document.querySelectorAll('.saveSectionBtn').forEach(b=>b.onclick=()=>saveDeepSection(b.dataset.text,b.dataset.section,b.dataset.kind));
  $('saveDeepResult')?.addEventListener('click',saveDeepCheckpoint);
}
function draftKey(){return `carmen_deepdraft_${currentProjectId||'none'}`}
function saveDeepDraft(){if(!currentProjectId||!$('deepQuestion'))return;localStorage.setItem(draftKey(),JSON.stringify({question:$('deepQuestion').value,referenceId:$('deepRef').value,focus:window.__deepFocus||{focus:'',kind:'root'},parentId:window.__deepParentId||null,savedAt:new Date().toISOString()}))}
function loadDeepDraft(){try{const d=JSON.parse(localStorage.getItem(draftKey())||'null');if(!d)return;if(d.referenceId&&[...$('deepRef').options].some(o=>o.value===d.referenceId))$('deepRef').value=d.referenceId;if(d.question)$('deepQuestion').value=d.question;window.__deepFocus=d.focus||{focus:'',kind:'root'};window.__deepParentId=d.parentId||null}catch{}}
async function runDeepDive(focus='',kind='root'){
  const refId=$('deepRef').value,ref=(await all('refs')).find(r=>r.id===refId);
  if(!ref)return toast('Select a saved reference first.');
  const url=$('backend').value.trim().replace(/\/$/,'');if(!url)return toast('Enter the Worker URL first.');
  saveDeepDraft(); $('deepRun').disabled=true; $('deepResult').innerHTML='<div class="claim">Carmen is exploring this branch…</div>';
  try{
    const r=await fetch(url+'/deepdive',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({imageDataUrl:ref.imageDataUrl,title:ref.title,url:ref.url,sourceType:ref.sourceType,sourceName:ref.sourceName,context:ref.context,analysis:{observations:ref.observations,inferences:ref.inferences,unknowns:ref.unknowns,relationships:ref.relationships,candidatePatterns:ref.candidatePatterns},question:$('deepQuestion').value,focus,focusKind:kind,parentFocus:window.__deepParentId||null})});
    const text=await r.text();let d;try{d=JSON.parse(text)}catch{throw Error(text||`HTTP ${r.status}`)}if(!r.ok||d.error)throw Error(d.error||`HTTP ${r.status}`);
    window.__deepResult=d;window.__deepFocus={focus,kind};renderDeepResult(d);await renderDeepTree();saveDeepDraft();toast('Deep dive complete.');
  }catch(e){$('deepResult').innerHTML='';toast(e.message)}finally{$('deepRun').disabled=false}
}
function nodeTitle(n){return n.title||n.focus||n.question||'Investigation branch'}
function nodeLabel(n){const map={root:'Deep dive',deconstruction:'Deconstruction',hazard:'Hazard',safety:'Safety',physical:'Physical plausibility',alternative:'Alternative',question:'Question',boundary:'Boundary',section:'Saved section'};return map[n.kind]||'Branch'}
async function renderDeepTree(){
  const nodes=(await all('deepdives')).filter(d=>d.projectId===currentProjectId).sort((a,b)=>String(a.createdAt).localeCompare(String(b.createdAt)));
  const byParent=new Map();nodes.forEach(n=>{const p=n.parentId||'__root__';if(!byParent.has(p))byParent.set(p,[]);byParent.get(p).push(n)});
  const roots=byParent.get('__root__')||[];
  function node(n,depth=0){const children=byParent.get(n.id)||[];return `<div class="tree-node ${depth===0?'root':''}"><div><b>${deepEsc(nodeLabel(n))}</b> <span class="focus">${deepEsc(nodeTitle(n))}</span> <span class="badge">${deepEsc(n.status||'complete')}</span></div><small>${new Date(n.createdAt).toLocaleString()}</small><div class="branch-actions"><button class="loadDeep smallbtn" data-id="${deepEsc(n.id)}">Load</button><button class="continueDeep smallbtn" data-id="${deepEsc(n.id)}">Branch here</button><button class="siblingDeep smallbtn" data-id="${deepEsc(n.id)}">New sibling</button></div>${children.length?`<div class="tree-children">${children.map(x=>node(x,depth+1)).join('')}</div>`:''}</div>`}
  let html=roots.map(r=>node(r)).join('');const orphan=nodes.filter(n=>n.parentId&&!nodes.some(p=>p.id===n.parentId));if(orphan.length)html+=`<div class="tree-node"><b>Recovered / orphaned nodes</b>${orphan.map(n=>node(n,1)).join('')}</div>`;
  $('deepTree').innerHTML=html||'<span class="muted">Nothing saved yet. Run a deep dive, then save the result or any individual section.</span>';
  document.querySelectorAll('.loadDeep').forEach(b=>b.onclick=loadDeepNode);
  document.querySelectorAll('.continueDeep').forEach(b=>b.onclick=async()=>{const n=(await all('deepdives')).find(x=>x.id===b.dataset.id);if(!n)return;$('deepRef').value=n.referenceId;$('deepQuestion').value=`Continue from: ${nodeTitle(n)}`;window.__deepParentId=n.id;window.__deepCurrentNodeId=n.id;window.__deepFocus={focus:n.focus||nodeTitle(n),kind:n.kind||'root'};if(n.result)window.__deepResult=n.result;setTab('deepDive');renderDeepResult(n.result||null);saveDeepDraft()});
  document.querySelectorAll('.siblingDeep').forEach(b=>b.onclick=async()=>{const n=(await all('deepdives')).find(x=>x.id===b.dataset.id);if(!n)return;$('deepRef').value=n.referenceId;$('deepQuestion').value='Explore a new branch alongside: '+nodeTitle(n);window.__deepParentId=n.parentId||null;window.__deepCurrentNodeId=null;window.__deepResult=null;window.__deepFocus={focus:'',kind:'root'};setTab('deepDive');$('deepResult').innerHTML='';saveDeepDraft()});
}
async function loadDeepNode(e){const d=(await all('deepdives')).find(x=>x.id===e.currentTarget.dataset.id);if(!d)return;$('deepRef').value=d.referenceId;$('deepQuestion').value=d.question||'';window.__deepResult=d.result||null;window.__deepFocus={focus:d.focus||'',kind:d.kind||'root'};window.__deepParentId=d.parentId||null;window.__deepCurrentNodeId=d.id;if(d.result)renderDeepResult(d.result);setTab('deepDive');saveDeepDraft()}
async function loadDeepRefs(){const refs=(await all('refs')).filter(r=>r.projectId===currentProjectId);$('deepRef').innerHTML=refs.map(r=>`<option value="${esc(r.id)}">${esc(r.title||r.url||r.id)}</option>`).join('')||'<option value="">No saved references</option>';loadDeepDraft()}
async function saveDeepSection(text,section,kind){
  const refId=$('deepRef').value;if(!refId||!text)return toast('Nothing to save.');
  const id='deep_'+crypto.randomUUID();const item={id,projectId:currentProjectId,createdAt:new Date().toISOString(),referenceId:refId,question:$('deepQuestion').value,result:{title:section,deconstruction:[],hazards:[],safetyArchitecture:[],physicalPlausibility:[],alternatives:[],nextQuestions:[],boundary:[]},focus:text,kind:kind||'section',status:'complete',parentId:window.__deepCurrentNodeId||window.__deepParentId||null};
  if(kind==='hazard')item.result.hazards=[{text}];else if(kind==='safety')item.result.safetyArchitecture=[{text}];else if(kind==='alternative')item.result.alternatives=[{text}];else if(kind==='question')item.result.nextQuestions=[{text}];else if(kind==='physical')item.result.physicalPlausibility=[{text}];else if(kind==='boundary')item.result.boundary=[{text}];else item.result.deconstruction=[{text}];
  await put('deepdives',item);await put('events',{id:'evt_'+crypto.randomUUID(),projectId:currentProjectId,type:'deep_dive_section_saved',at:new Date().toISOString(),deepDiveId:id,parentDeepDiveId:item.parentId||null});window.__deepCurrentNodeId=id;window.__deepParentId=id;await renderDeepTree();toast('Saved as a research node.');
}
async function saveDeepCheckpoint(){
  const refId=$('deepRef').value;if(!refId)return toast('Select a reference first.');if(!window.__deepResult)return toast('Run a deep dive before saving the result.');
  const id='deep_'+crypto.randomUUID();const result=window.__deepResult;const item={id,projectId:currentProjectId,createdAt:new Date().toISOString(),referenceId:refId,question:$('deepQuestion').value,result,focus:window.__deepFocus?.focus||'',kind:window.__deepFocus?.kind||'root',status:'complete',title:result.title||'Deep dive',parentId:window.__deepParentId||null};
  await put('deepdives',item);await put('events',{id:'evt_'+crypto.randomUUID(),projectId:currentProjectId,type:'deep_dive_checkpoint',at:new Date().toISOString(),deepDiveId:id,parentDeepDiveId:item.parentId||null});window.__deepParentId=id;window.__deepCurrentNodeId=id;await renderDeepTree();localStorage.removeItem(draftKey());toast('Saved to the investigation tree.');
}
function graphSourceLabel(n){return ({reference:'Reference',pattern:'Pattern',deepdive:'Deep dive',finding:'Finding',hazard:'Hazard',safety:'Safety',physical:'Physical',alternative:'Alternative',question:'Question',boundary:'Boundary',lead:'Research lead',queue:'Research queue'}[n.type]||'Node')}
async function buildEvidenceGraph(){
  const [refs,deepdives,leads,queue]=await Promise.all([all('refs'),all('deepdives'),all('leads'),all('queue')]);
  const R=refs.filter(x=>x.projectId===currentProjectId),D=deepdives.filter(x=>x.projectId===currentProjectId),L=leads.filter(x=>x.projectId===currentProjectId),Q=queue.filter(x=>x.projectId===currentProjectId);
  const nodes=[],edges=[];const add=(id,type,title,data={})=>{if(!nodes.some(n=>n.id===id))nodes.push({id,type,title:String(title||type),...data})};const edge=(a,b,rel)=>{if(a&&b&&a!==b&&!edges.some(e=>e.a===a&&e.b===b&&e.rel===rel))edges.push({a,b,rel})};
  R.forEach(r=>add('ref:'+r.id,'reference',r.title||r.url||r.id,{refId:r.id,url:r.url,source:r.sourceName||r.sourceType,createdAt:r.createdAt,summary:(r.signature||r.context||'')}));
  const patterns=buildPatterns(R);patterns.forEach(p=>{const id='pattern:'+patternKey(p.label);add(id,'pattern',p.label,{confidence:p.confidence,count:p.evidenceCount});p.evidenceIds.forEach(rid=>edge('ref:'+rid,id,'supports'));});
  D.forEach(d=>{const id='deep:'+d.id;add(id,'deepdive',d.title||nodeTitle(d),{deepId:d.id,focus:d.focus,question:d.question,createdAt:d.createdAt,summary:d.result?.title||''});edge('ref:'+d.referenceId,id,'deep-dives');if(d.parentId)edge('deep:'+d.parentId,id,'branches-to');
    const sections=[['deconstruction','finding'],['hazards','hazard'],['safetyArchitecture','safety'],['physicalPlausibility','physical'],['alternatives','alternative'],['nextQuestions','question'],['boundary','boundary']];
    for(const [key,type] of sections){for(const item of (d.result?.[key]||[])){const text=String(item?.text||item||'').trim();if(!text)continue;const sid=`section:${d.id}:${type}:${text}`;add(sid,type,text,{deepId:d.id,section:key,summary:text});edge(id,sid,'contains');}}
  });
  L.forEach(l=>{const id='lead:'+l.id;add(id,'lead',l.text||'Research lead',{status:l.status,createdAt:l.createdAt,summary:l.text||''});(l.refIds||[]).forEach(rid=>edge('ref:'+rid,id,'raises'));});
  Q.forEach(q=>{const id='queue:'+q.id;add(id,'queue',q.label||q.url,{url:q.url,status:q.status,note:q.note,createdAt:q.createdAt});});
  return {nodes,edges};
}
async function loadDeepNodeById(id){const d=(await all('deepdives')).find(x=>x.id===id);if(!d)return;$('deepRef').value=d.referenceId;$('deepQuestion').value=d.question||'';window.__deepResult=d.result||null;window.__deepFocus={focus:d.focus||'',kind:d.kind||'root'};window.__deepParentId=d.parentId||null;window.__deepCurrentNodeId=d.id;if(d.result)renderDeepResult(d.result);setTab('deepDive');saveDeepDraft()}
