async function buildIntelligence(){
  const refs=(await all('refs')).filter(r=>r.projectId===currentProjectId);
  const leads=(await all('leads')).filter(l=>l.projectId===currentProjectId);
  const queue=(await all('queue')).filter(q=>q.projectId===currentProjectId);
  const deep=(await all('deepdives')).filter(d=>d.projectId===currentProjectId);
  const patterns=buildPatterns(refs);
  const graph=await buildEvidenceGraph();
  const findings=deep.filter(d=>d.kind==='deconstruction'||d.kind==='root'||d.kind==='section');
  const questions=[];
  const hazards=[];
  const alternatives=[];
  for(const d of deep){
    for(const x of (d.result?.nextQuestions||[])) { const t=deepText(x); if(t) questions.push({text:t,node:d}); }
    for(const x of (d.result?.hazards||[])) { const t=deepText(x); if(t) hazards.push({text:t,node:d}); }
    for(const x of (d.result?.alternatives||[])) { const t=deepText(x); if(t) alternatives.push({text:t,node:d}); }
  }
  const support=patterns.map(p=>({text:p.text||p.label||String(p),count:p.count||p.refs?.length||1}));
  const weak=support.filter(x=>x.count<=1).slice(0,8);
  const next=[];
  questions.slice(0,6).forEach(q=>next.push({priority:'high',reason:'Open question from a saved Deep Dive',text:q.text}));
  weak.slice(0,4).forEach(x=>next.push({priority:'medium',reason:'Pattern has limited independent support',text:`Test this pattern against another source: ${x.text}`}));
  queue.filter(q=>q.status!=='completed').slice(0,4).forEach(q=>next.push({priority:'medium',reason:'Already queued research',text:q.text||q.title||q.url||'Queued research item'}));
  leads.filter(l=>l.status==='new').slice(0,3).forEach(l=>next.push({priority:'low',reason:'Unreviewed research lead',text:l.text}));
  const contradictions=[];
  const seen=new Map();
  for(const d of deep){
    const vals=[...(d.result?.deconstruction||[]),...(d.result?.physicalPlausibility||[])].map(deepText).filter(Boolean);
    for(const v of vals){const key=v.toLowerCase().replace(/[^a-z0-9 ]/g,'').split(/\s+/).slice(0,10).join(' ');if(key)seen.set(key,(seen.get(key)||0)+1)}
  }
  // Structural contradiction candidates: explicit differences in saved leads/questions, never asserted as factual contradictions.
  const diffLeads=leads.filter(l=>/contradict|conflict|inconsistent|different|disagree/i.test(l.text||''));
  diffLeads.slice(0,6).forEach(l=>contradictions.push(l.text));
  const gaps=[];
  if(!refs.length)gaps.push('No saved evidence yet.');
  if(refs.length===1)gaps.push('Only one source is saved; cross-source corroboration is unavailable.');
  if(questions.length)gaps.push(`${questions.length} open question${questions.length===1?'':'s'} remain in Deep Dive nodes.`);
  if(weak.length)gaps.push(`${weak.length} recurring pattern${weak.length===1?'':'s'} currently have only one recorded support path.`);
  if(!leads.length)gaps.push('No research leads have been generated yet.');
  const confidence=refs.length>=4?'moderate-to-strong':refs.length>=2?'developing':'early';
  return {refs,deep,patterns,support,questions,hazards,alternatives,weak,next,contradictions,gaps,confidence,graphNodes:graph.nodes.length,graphEdges:graph.edges.length,findings};
}
async function renderIntelligence(){
  const box=$('intelligenceWorkspace');if(!box)return;
  const x=await buildIntelligence();
  $('intelStats').innerHTML=`<div class="stat"><div><div class="num">${x.next.length}</div><small>Next moves</small></div><div><div class="num">${x.gaps.length}</div><small>Gaps</small></div><div><div class="num">${x.weak.length}</div><small>Weak patterns</small></div><div><div class="num">${x.questions.length}</div><small>Open questions</small></div></div>`;
  const block=(title,items,empty='Nothing surfaced yet.')=>`<div class="intel-block"><h4>${esc(title)}</h4>${items.length?items.map(i=>`<div class="intel-item">${typeof i==='string'?esc(i):`<b>${esc(i.priority||'')}</b> ${esc(i.text)}`}<small>${typeof i==='string'?'':esc(i.reason||'')}</small></div>`).join(''):`<span class="muted">${esc(empty)}</span>`}</div>`;
  $('intelligenceWorkspace').innerHTML=`<div class="card"><div class="sectionhead"><h3>Investigation signal</h3><span class="badge">${esc(x.confidence)} evidence base</span></div><p class="muted">This layer reasons from Carmen's saved structure. It does not turn weak evidence into certainty. “Contradiction” items are candidates for review, not verdicts.</p>${block('Next investigations',x.next,'No obvious next move. Your investigation may simply need more evidence.')}${block('Evidence gaps',x.gaps)}${block('Potential contradictions',x.contradictions,'No explicit conflict language found in saved leads.')}${block('Under-supported patterns',x.weak.map(w=>`${w.text} — ${w.count} support path${w.count===1?'':'s'}`),'No low-support patterns surfaced.')}${block('Open Deep Dive questions',x.questions.map(q=>q.text),'No open questions surfaced.')}${block('Flagged safety variables',x.hazards.map(h=>'⚠️ '+h.text),'No saved hazards surfaced.')}${block('Safer conceptual alternatives',x.alternatives,'No alternatives saved yet.')}<div class="muted small" style="margin-top:10px">Graph: ${x.graphNodes} nodes · ${x.graphEdges} connections · ${x.refs.length} sources · ${x.deep.length} deep-dive nodes</div></div>`;
}
async function saveIntelligenceSnapshot(){
  const x=await buildIntelligence();
  await put('events',{id:'evt_'+crypto.randomUUID(),projectId:currentProjectId,type:'intelligence_snapshot',at:new Date().toISOString(),summary:{confidence:x.confidence,next:x.next.slice(0,10),gaps:x.gaps,contradictions:x.contradictions,weakPatterns:x.weak.map(w=>w.text)}});
  toast('Intelligence snapshot saved to the investigation history.');
}
